using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;
    vector<int> a(N + 1);
    vector<int> indeg(N + 1, 0);

    for (int i = 1; i <= N; i++) {
        cin >> a[i];
        indeg[a[i]]++;
    }

    // Min-heap of available cards
    priority_queue<int, vector<int>, greater<int>> pq;
    for (int i = 1; i <= N; i++) {
        if (indeg[i] == 0) {
            pq.push(i);
        }
    }

    vector<int> result;
    // To keep track of what we've used
    vector<bool> used(N + 1, false);

    while (!pq.empty()) {
        int cur = pq.top();
        pq.pop();
        if (used[cur]) continue;
        used[cur] = true;
        result.push_back(cur);

        // When we place cur, the card a[cur] has one less incoming dependency
        indeg[a[cur]]--;
        if (indeg[a[cur]] == 0 && !used[a[cur]]) {
            pq.push(a[cur]);
        }
    }

    if ((int)result.size() != N) {
        cout << -1 << '\n';
    } else {
        for (int i = 0; i < N; i++) {
            cout << result[i] << (i + 1 == N ? '\n' : ' ');
        }
    }

    return 0;
}

