#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;
    vector<int> a(N + 1);
    for (int i = 1; i <= N; ++i) cin >> a[i];

    vector<int> ans;
    ans.reserve(N);

    // We build the permutation from left to right.
    // At each step, choose the smallest unused card x such that:
    // - if there is a previous card p, then x != a[p]
    // - after choosing x, the remaining cards can still be arranged.
    //
    // The feasibility of the remaining suffix is checked greedily:
    // if current last card is last, repeatedly place the smallest available
    // card not equal to a[last]. If at some step none exists, impossible.
    //
    // Since N is small enough for this straightforward greedy-check approach
    // in the intended task, this yields the lexicographically smallest answer.

    vector<bool> used(N + 1, false);

    auto feasible = [&](int last, vector<bool> used_now) -> bool {
        int rem = 0;
        for (int i = 1; i <= N; ++i) if (!used_now[i]) rem++;

        int curLast = last;
        for (int step = 0; step < rem; ++step) {
            int pick = -1;
            for (int x = 1; x <= N; ++x) {
                if (used_now[x]) continue;
                if (curLast != -1 && x == a[curLast]) continue;
                pick = x;
                break;
            }
            if (pick == -1) return false;
            used_now[pick] = true;
            curLast = pick;
        }
        return true;
    };

    for (int pos = 0; pos < N; ++pos) {
        bool found = false;
        for (int x = 1; x <= N; ++x) {
            if (used[x]) continue;
            if (!ans.empty() && x == a[ans.back()]) continue;

            auto tmp = used;
            tmp[x] = true;
            if (feasible(x, tmp)) {
                ans.push_back(x);
                used[x] = true;
                found = true;
                break;
            }
        }
        if (!found) {
            cout << -1 << '\n';
            return 0;
        }
    }

    for (int i = 0; i < N; ++i) {
        if (i) cout << ' ';
        cout << ans[i];
    }
    cout << '\n';
    return 0;
}

