public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] a = new int[n + 1];
        for (int i = 1; i <= n; i++) a[i] = sc.nextInt();

        TreeSet<Integer> remaining = new TreeSet<>();
        for (int i = 1; i <= n; i++) remaining.add(i);

        int[] result = new int[n];
        int last = 0; // no last card yet

        for (int pos = 0; pos < n; pos++) {
            boolean placed = false;
            for (int c : new ArrayList<>(remaining)) {
                if (last != 0 && c == a[last]) continue; // forbidden
                // Check if placing c leads to dead end
                remaining.remove(c);
                if (remaining.size() == 1) {
                    int only = remaining.first();
                    if (only == a[c]) {
                        remaining.add(c);
                        continue; // dead end
                    }
                }
                result[pos] = c;
                last = c;
                placed = true;
                break;
            }
            if (!placed) {
                System.out.println(-1);
                return;
            }
        }

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) sb.append(result[i]).append(i < n-1 ? " " : "\n");
        System.out.print(sb);
    }
}

