public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int N = fs.nextInt();
        int[] a = new int[N + 1];
        for (int i = 1; i <= N; i++) a[i] = fs.nextInt();

        if (N == 1) {
            System.out.println(1);
            return;
        }

        int[] indeg = new int[N + 1];
        for (int i = 1; i <= N; i++) indeg[a[i]]++;

        TreeSet<Integer> starts = new TreeSet<>();
        for (int i = 1; i <= N; i++) {
            if (indeg[i] == 0) starts.add(i);
        }

        int[] ans = new int[N];
        boolean[] used = new boolean[N + 1];

        for (int pos = 0; pos < N; pos++) {
            Integer x = starts.pollFirst();
            if (x == null) {
                System.out.println(-1);
                return;
            }
            ans[pos] = x;
            used[x] = true;

            int y = a[x];
            indeg[y]--;
            if (indeg[y] == 0 && !used[y]) starts.add(y);
        }

        for (int i = 0; i + 1 < N; i++) {
            if (a[ans[i]] == ans[i + 1]) {
                System.out.println(-1);
                return;
            }
        }

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < N; i++) {
            if (i > 0) sb.append(' ');
            sb.append(ans[i]);
        }
        System.out.println(sb);
    }
}

