#define MAXN 200005

int a[MAXN];
int indeg[MAXN], outdeg[MAXN];
int forbid[MAXN];
int heap[MAXN];
int heap_size = 0;

void swap(int *a, int *b) {
    int t = *a;
    *a = *b;
    *b = t;
}

void push(int x) {
    heap[heap_size] = x;
    int i = heap_size;
    heap_size++;
    while (i > 0 && heap[(i-1)/2] > heap[i]) {
        swap(&heap[(i-1)/2], &heap[i]);
        i = (i-1)/2;
    }
}

int pop() {
    int res = heap[0];
    heap_size--;
    heap[0] = heap[heap_size];
    int i = 0;
    while (1) {
        int smallest = i;
        int left = 2*i+1;
        int right = 2*i+2;
        if (left < heap_size && heap[left] < heap[smallest]) smallest = left;
        if (right < heap_size && heap[right] < heap[smallest]) smallest = right;
        if (smallest == i) break;
        swap(&heap[i], &heap[smallest]);
        i = smallest;
    }
    return res;
}

int empty() {
    return heap_size == 0;
}

int main() {
    int n;
    scanf("%d", &n);
    for (int i = 1; i <= n; i++) {
        scanf("%d", &a[i]);
        forbid[i] = a[i];
        outdeg[i] = 1;
        indeg[a[i]]++;
    }

    // Check basic feasibility: each node can have at most one incoming forbidden edge
    // Actually we need to check if a Hamiltonian path exists in the complement graph.
    // For this problem, we can greedily construct it.

    // Push all nodes with indeg == 0 or nodes that can be first
    for (int i = 1; i <= n; i++) {
        if (indeg[i] == 0) {
            push(i);
        }
    }

    int result[MAXN];
    int res_len = 0;
    int last = -1;

    while (!empty()) {
        int u = pop();
        if (last != -1 && forbid[last] == u) {
            // Cannot place u after last, try another
            if (empty()) {
                printf("-1\n");
                return 0;
            }
            int v = pop();
            push(u);
            u = v;
        }
        result[res_len++] = u;
        // When we place u, we effectively reduce indeg of forbid[u]?
        // Actually, we just need to ensure we don't put forbid[u] right after u.
        // We can push forbid[u] if it becomes available now.
        // But indeg counts how many nodes cannot have it on their right.
        // After placing u, we "use" one of those restrictions.
        indeg[forbid[u]]--;
        if (indeg[forbid[u]] == 0) {
            push(forbid[u]);
        }
        last = u;
    }

    if (res_len != n) {
        printf("-1\n");
        return 0;
    }

    for (int i = 0; i < n; i++) {
        printf("%d ", result[i]);
    }
    printf("\n");
    return 0;
}

