#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int *bit;
    int n;
} Fenwick;

void fw_init(Fenwick *fw, int n) {
    fw->n = n;
    fw->bit = (int*)calloc(n + 1, sizeof(int));
}

void fw_add(Fenwick *fw, int idx, int val) {
    for (; idx <= fw->n; idx += idx & -idx) fw->bit[idx] += val;
}

int fw_sum(Fenwick *fw, int idx) {
    int s = 0;
    for (; idx > 0; idx -= idx & -idx) s += fw->bit[idx];
    return s;
}

int fw_kth(Fenwick *fw, int k) {
    int idx = 0;
    int bit = 1;
    while ((bit << 1) <= fw->n) bit <<= 1;
    for (; bit; bit >>= 1) {
        int nxt = idx + bit;
        if (nxt <= fw->n && fw->bit[nxt] < k) {
            idx = nxt;
            k -= fw->bit[nxt];
        }
    }
    return idx + 1;
}

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    int *a = (int*)malloc((N + 1) * sizeof(int));
    for (int i = 1; i <= N; i++) scanf("%d", &a[i]);

    if (N == 1) {
        printf("1\n");
        free(a);
        return 0;
    }

    int *indeg = (int*)calloc(N + 1, sizeof(int));
    int *to = (int*)malloc((N + 1) * sizeof(int));
    for (int i = 1; i <= N; i++) {
        to[i] = a[i];
        indeg[a[i]]++;
    }

    /* Check if permutation graph is a single cycle.
       In that case impossible, because every adjacent pair in any Hamilton path
       would be forbidden. */
    int *vis = (int*)calloc(N + 1, sizeof(int));
    int cycles = 0;
    for (int i = 1; i <= N; i++) {
        if (!vis[i]) {
            int x = i;
            while (!vis[x]) {
                vis[x] = i;
                x = to[x];
            }
            if (vis[x] == i) cycles++;
        }
    }
    int is_perm = 1;
    for (int i = 1; i <= N; i++) {
        if (indeg[i] != 1) {
            is_perm = 0;
            break;
        }
    }
    if (is_perm && cycles == 1) {
        printf("-1\n");
        free(a); free(indeg); free(to); free(vis);
        return 0;
    }

    /* Greedy with Fenwick:
       choose smallest available x, unless x == forbidden(previous),
       then choose second smallest if exists.
       For this problem, the only impossible case is the single cycle above. */
    Fenwick fw;
    fw_init(&fw, N);
    for (int i = 1; i <= N; i++) fw_add(&fw, i, 1);

    int *ans = (int*)malloc(N * sizeof(int));
    int prev = -1;

    for (int pos = 0; pos < N; pos++) {
        int rem = fw_sum(&fw, N);
        int first = fw_kth(&fw, 1);
        int pick;

        if (prev != -1 && first == a[prev]) {
            if (rem == 1) {
                printf("-1\n");
                free(a); free(indeg); free(to); free(vis); free(fw.bit); free(ans);
                return 0;
            }
            pick = fw_kth(&fw, 2);
        } else {
            pick = first;
        }

        ans[pos] = pick;
        fw_add(&fw, pick, -1);
        prev = pick;
    }

    for (int i = 0; i < N; i++) {
        if (i) printf(" ");
        printf("%d", ans[i]);
    }
    printf("\n");

    free(a);
    free(indeg);
    free(to);
    free(vis);
    free(fw.bit);
    free(ans);
    return 0;
}
